const bug = $input.item.json.output;
const storyKey = $('Parse Story Key & Bug Text').item.json.storyKey;

let description = `*Steps to Reproduce:*\n${bug.stepsToReproduce}\n\n`;
description += `*Expected Result:*\n${bug.expectedResult}\n\n`;
description += `*Actual Result:*\n${bug.actualResult}\n\n`;
description += `*Severity:* ${bug.severity} - ${bug.severityJustification}\n\n`;
if (storyKey) {
  description += `*Related Story:* ${storyKey}\n`;
}
description += `\n_This bug report was drafted by the Smart Bug Report Agent and should be reviewed before confirming._`;

return [{
  json: {
    title: bug.title,
    description,
    severity: bug.severity,
    storyKey
  }
}];

const created = $input.item.json;
const payload = $('Prepare Jira Payload').item.json;

const bugKey = created.key || created.id || 'UNKNOWN';

let md = `**New Bug Created:** ${bugKey}\n\n`;
md += `**Title:** ${payload.title}\n\n`;
md += `**Severity:** ${payload.severity}\n\n`;
if (payload.storyKey) {
  md += `**Related Story:** ${payload.storyKey}\n\n`;
}
md += `${payload.description}`;

return [{
  json: {
    output: md,
    bugKey,
    storyKey: payload.storyKey
  }
}];
